void Solver::bump_var(int var, double coeff) {
    if (coeff == 0.0) return;
    const double MAX_ACT = 1e100;
    const double RESCALE = 1e-100;

    // Increment activity
    activity[var] += var_inc * coeff;

    // Rescale all activities only when necessary
    if (activity[var] > MAX_ACT) {
        double *act = activity + 1;               // activity[1] ... activity[vars]
        for (int i = vars; i > 0; --i) {
            *act++ *= RESCALE;
        }
        var_inc *= RESCALE;
    }

    // Keep VSIDS heap consistent
    if (vsids.inHeap(var)) vsids.update(var);
}
